CTX=ROOT.parent/'context'
assert 'transcription frozen' in (ROOT/'progress.log').read_text()
assert 'context opened' in (ROOT/'progress.log').read_text()
NOTES=[]
C='`same_cote_33/MPL_33_098-146_notes.md`'
